import React, { useMemo, useState } from "react";
import { AppShell, Theme, KpiCard, DonutChart, BarList, AreaChart, Kanban, TableView, SampleBanner, SpotlightCard, PrintButton, Badge, Card, CardHeader, CardBody, Grid, Button, toast } from "@ocsc/ui";
import { useTable } from "@ocsc/app";
import { IfcView } from "@ocsc/ifc";
import { Boxes, LayoutDashboard, Columns3, Table2, Download } from "lucide-react";
import { ExportPanel } from "./ExportPanel";

export default function App() {
  const clashes = useTable("clashes");
  const rows = clashes.rows as any[];
  const byStatus = useMemo(() => ["Open","In review","Resolved","Closed"].map((s) => ({ label: s, value: rows.filter((r) => r.status === s).length })), [rows]);
  const byDiscipline = useMemo(() => ["Structure","MEP","Architecture","Civil"].map((d) => ({ label: d, value: rows.filter((r) => r.discipline === d).length })), [rows]);
  const trend = rows.slice(0, 8).map((r, i) => ({ week: "W" + (i + 1), clashes: Number(r.count) }));
  const pages = [
    { id: "overview", label: "Overview", icon: <LayoutDashboard />, render: () => (
      <div className="space-y-6">
        <SampleBanner tables={[clashes]} />
        <Grid cols={4}>
          <KpiCard label="Open clashes" value={byStatus[0].value} delta={-12} trend={[9,8,8,7,6,5]} />
          <KpiCard label="In review" value={byStatus[1].value} trend="up" />
          <KpiCard label="Resolved" value={byStatus[2].value} format="number" />
          <KpiCard label="Total" value={rows.length} />
        </Grid>
        <Grid cols={2}>
          <Card><CardHeader title="By status" /><CardBody><DonutChart data={byStatus} /></CardBody></Card>
          <Card><CardHeader title="By discipline" /><CardBody><BarList data={byDiscipline} /></CardBody></Card>
        </Grid>
        <Card><CardHeader title="Clash trend" /><CardBody><AreaChart data={trend} xKey="week" yKey="clashes" /></CardBody></Card>
        <SpotlightCard title="Needs attention" description={rows.filter((r) => r.priority === "High").length + " high-priority clashes"} />
      </div>) },
    { id: "model", label: "Model", icon: <Boxes />, render: () => (
      <Card><CardHeader title="Federated model" /><CardBody><IfcView /></CardBody></Card>) },
    { id: "board", label: "Board", icon: <Columns3 />, count: rows.length, render: () => (
      <Kanban rows={rows} groupBy="status" columns={["Open","In review","Resolved","Closed"].map((v) => ({ value: v }))}
        renderCard={(r: any) => <div className="space-y-1"><div className="font-medium">{r.title}</div><Badge>{r.discipline}</Badge></div>}
        onMove={(r: any, value) => clashes.update(r._id, { status: value })} />) },
    { id: "register", label: "Register", icon: <Table2 />, render: () => (
      <div className="space-y-4"><div className="flex justify-end"><PrintButton title="Clash register" /></div><TableView table={clashes} /></div>) },
    { id: "exports", label: "Exports", icon: <Download />, render: () => <ExportPanel rows={rows} /> },
  ];
  return (
    <Theme preset="crisp" density="comfortable">
      <AppShell title="BIM Coordination Hub" pages={pages} commands={[{ label: "Export DXF", action: () => toast("Use the Exports tab") }]} />
    </Theme>
  );
}

