import React, { useState } from "react";
import { Card, CardHeader, CardBody, Button, Callout } from "@ocsc/ui";
import { downloadDxf, parseDxf } from "@ocsc/dxf";
import { downloadCsv, downloadWorkbook } from "@ocsc/sheets";
import { Drawing, DrawingLine, DrawingCircle, DrawingText, Dim } from "@ocsc/plot";

export function ExportPanel({ rows }: { rows: any[] }) {
  const [parsed, setParsed] = useState<string | null>(null);
  const grid = [0, 6000, 12000, 18000];
  return (
    <div className="space-y-4">
      <Card><CardHeader title="Grid drawing" /><CardBody>
        <Drawing bounds={[-1000, -1000, 19000, 7000]} units="mm">
          {grid.map((x) => <DrawingLine key={x} from={[x, 0]} to={[x, 6000]} />)}
          {grid.map((x, i) => <DrawingCircle key={"c" + x} center={[x, 6500]} r={300} />)}
          {grid.map((x, i) => <DrawingText key={"t" + x} at={[x, 6500]} text={String.fromCharCode(65 + i)} />)}
          <Dim from={[0, 0]} to={[6000, 0]} offset={-600} label="6000" />
        </Drawing>
      </CardBody></Card>
      <div className="flex flex-wrap gap-2">
        <Button onClick={() => downloadDxf("grid.dxf", { units: "mm", layers: [{ name: "GRID", color: 8 }], entities: grid.map((x) => ({ type: "line", layer: "GRID", from: { x, y: 0 }, to: { x, y: 6000 } })) })}>Download DXF</Button>
        <Button variant="outline" onClick={() => downloadCsv("clashes.csv", [["Title","Status"], ...rows.map((r) => [r.title, r.status])])}>CSV</Button>
        <Button variant="outline" onClick={() => downloadWorkbook("clashes.xlsx", [{ name: "Clashes", rows: [["Title","Status"], ...rows.map((r) => [r.title, r.status])] }])}>Excel</Button>
      </div>
      <input type="file" accept=".dxf" onChange={(e) => { const f = e.target.files?.[0]; if (!f) return; const rd = new FileReader(); rd.onload = () => { const d = parseDxf(String(rd.result)); setParsed(d.entities.length + " entities"); }; rd.readAsText(f); }} />
      {parsed && <Callout tone="info">{parsed}</Callout>}
    </div>
  );
}

