import React, { useMemo, useRef, useState } from "react";
import { analyseBeam, barArea, barRow, convert, sectionProps, type BeamInput } from "@ocsc/eng";
import { CalcRows, CalcSheet, CheckSummary, Tex, type CalcRow } from "@ocsc/math";
import { BeamResults, SectionDrawing, Plot, InteractionDiagram } from "@ocsc/plot";
import { AppShell, Card, CardBody, CardHeader, Field, Grid, Input, KpiCard, PrintButton, Theme, Callout } from "@ocsc/ui";
import { Calculator, Ruler, LineChart } from "lucide-react";

export default function App() {
  const [span, setSpan] = useState(6);
  const [w, setW] = useState(25);
  const b = 300, h = 550;
  const bars = barRow({ n: 3, dia: 20, b, h, cover: 30, link: 10 });
  const As = barArea(3, 20);
  const props = sectionProps({ type: "rect", b, h });
  const beam: BeamInput = useMemo(() => ({ length: span, supports: [{ x: 0, type: "pin" }, { x: span, type: "roller" }], loads: [{ type: "udl", w }], EI: convert(33, "GPa", "kN/m2") * convert((b * h ** 3) / 12, "mm4", "m4") }), [span, w]);
  const result = useMemo(() => analyseBeam(beam), [beam]);
  const rows: CalcRow[] = [
    { kind: "step", label: "Design moment", symbol: "M_{Ed}", formula: "w L^2 / 8", values: { w, L: span }, result: (w * span * span) / 8, unit: "kNm", reference: "Statics" },
    { kind: "check", label: "Bending", symbol: "M_{Ed}", limitSymbol: "M_{Rd}", value: (w * span * span) / 8, limit: 250, unit: "kNm", reference: "EN 1992-1-1 6.1" },
  ] as any;
  return (
    <Theme preset="evolve" />,
    <AppShell title="Beam Designer" pages={[
      { id: "inputs", label: "Inputs", icon: <Ruler />, render: () => (
        <Grid cols={2}>
          <Card><CardHeader title="Loads" /><CardBody className="space-y-3">
            <Field label="Span (m)">{(id) => <Input id={id} type="number" value={span} onChange={(e) => setSpan(Number(e.target.value))} />}</Field>
            <Field label="UDL (kN/m)">{(id) => <Input id={id} type="number" value={w} onChange={(e) => setW(Number(e.target.value))} />}</Field>
            <KpiCard label="As provided" value={As} />
            <KpiCard label="Ix (mm4)" value={props.Ix} />
          </CardBody></Card>
          <Card><CardHeader title="Section" /><CardBody><SectionDrawing shape={{ type: "rect", b, h }} bars={bars} link={{ dia: 10, cover: 30 }} /></CardBody></Card>
        </Grid>) },
      { id: "results", label: "Results", icon: <LineChart />, render: () => (
        <div className="space-y-4">
          <BeamResults beam={beam} result={result} />
          <Plot series={[{ name: "Moment", data: result.x.map((x: number, i: number) => [x, result.moment[i]]) }]} x={{ label: "x", unit: "m" }} y={{ label: "M", unit: "kNm" }} />
          <InteractionDiagram curve={[[0, 3000], [200, 2000], [300, 800], [0, -500]]} points={[{ M: 120, N: 900, label: "Case 1" }]} />
        </div>) },
      { id: "calc", label: "Calc sheet", icon: <Calculator />, render: () => (
        <CalcSheet title="Beam B1" job="2410" by="AI" checked="KD" date="2026-11-17" revision="P01">
          <Tex math="M = \frac{w L^2}{8}" block />
          <CalcRows rows={rows} />
          <CheckSummary checks={[{ label: "Bending", utilisation: 0.72 }] as any} />
        </CalcSheet>) },
    ]} />
  );
}

import React, { useState } from "react";
import { AppShell, Theme, KpiCard, Gauge, GalleryView, TableView, RecordForm, Kanban, Whiteboard, MapView, SignaturePad, Accordion, Markdown, TreeView, OrgChart, SortableList, BentoGrid, BentoCard, Callout, EmptyState, Badge, Card, CardBody, CardHeader, Grid, Tabs, DatePicker, TagInput, Select, Switch } from "@ocsc/ui";
import { useTable } from "@ocsc/app";
import { IfcView } from "@ocsc/ifc";

export default function App() {
  const defects = useTable("defects");
  const rows = defects.rows as any[];
  const [board, setBoard] = useState<any>(null);
  const [tab, setTab] = useState("list");
  const [tags, setTags] = useState<string[]>(["roof"]);
  const [items, setItems] = useState([{ id: "1", label: "Roof" }, { id: "2", label: "Walls" }]);
  return (
    <Theme preset="forest">
      <AppShell title="Site Inspection Studio" pages={[
        { id: "overview", label: "Overview", render: () => (
          <BentoGrid>
            <BentoCard title="Pass rate"><Gauge value={82} max={100} /></BentoCard>
            <BentoCard title="Open defects"><KpiCard label="Open" value={rows.filter((r) => r.status !== "Closed").length} trend={[3, 5, "x", 4] as any} /></BentoCard>
            <BentoCard title="Notes"><Markdown>{"**Walkdown** complete for level 2."}</Markdown></BentoCard>
          </BentoGrid>) },
        { id: "defects", label: "Defects", count: rows.length, render: () => (
          <div className="space-y-4">
            <Tabs value={tab} onChange={setTab} tabs={[{ id: "list", label: "List" }, { id: "board", label: "Board" }, { id: "gallery", label: "Gallery" }]} />
            {tab === "list" && <TableView table={defects} />}
            {tab === "board" && <Kanban rows={rows} groupBy="status" renderCard={(r: any) => <div>{r.title}</div>} />}
            {tab === "gallery" && <GalleryView rows={rows} imageKey="photos" titleKey="title" />}
          </div>) },
        { id: "model", label: "Model", render: () => <IfcView asset="missing-asset-id" /> },
        { id: "markup", label: "Markup", render: () => (
          <div className="space-y-4">
            <Whiteboard value={board} onChange={setBoard} height={360} />
            <SignaturePad onChange={() => {}} />
          </div>) },
        { id: "map", label: "Map", render: () => <MapView markers={rows.map((r, i) => ({ id: r._id, lat: 53.34 + i * 0.001, lon: -6.26, label: r.title }))} /> },
        { id: "setup", label: "Setup", render: () => (
          <div className="space-y-4">
            <Accordion items={[{ id: "a", title: "Checklist", content: "Roof, walls, services" }]} />
            <TreeView items={[{ id: "1", label: "Block A", children: [{ id: "2", label: "Level 1" }] }] as any} />
            <OrgChart people={[{ id: "1", name: "Aoife", role: "Lead" }, { id: "2", name: "Brian", role: "Inspector", manager: "1" }] as any} />
            <SortableList items={items} onChange={setItems} render={(it: any) => it.label} />
            <TagInput value={tags} onChange={setTags} />
            <DatePicker value="2026-11-17" onChange={() => {}} />
            <Select value="a" onChange={() => {}} options={[{ value: "a", label: "A" }]} />
            <Switch checked onChange={() => {}} />
            <RecordForm table={defects} onDone={() => {}} />
            <EmptyState title="Nothing archived" />
          </div>) },
      ]} />
    </Theme>
  );
}
